+package com.example.service;
+
+import com.example.mapper.UserMapper;
+import com.example.model.User;
+
+import java.util.Arrays;
+import java.util.HashSet;
+import java.util.List;
+import java.util.Set;
+
+/**
+ * User service class
+ */
+public class UserService {
+
+    private static final Set<String> ALLOWED_ORDER_COLUMNS = new HashSet<>(Arrays.asList(
+            "id", "username", "email", "phone", "address", "create_time", "update_time", "status"
+    ));
+
+    private static final Set<String> ALLOWED_SORT_DIRECTIONS = new HashSet<>(Arrays.asList(
+            "ASC", "DESC"
+    ));
+
+    private UserMapper userMapper;
+
+    public UserService(UserMapper userMapper) {
+        this.userMapper = userMapper;
+    }
+
+    /**
+     * Query user list based on sorting field and direction provided by the user
+     * Using MyBatis dynamic SQL to implement ORDER BY sorting functionality
+     *
+     * @param orderBy Sorting field
+     * @param sortDirection Sorting direction
+     * @return User list
+     */
+    public List<User> getUsersByOrder(String orderBy, String sortDirection) {
+        if (orderBy == null || !ALLOWED_ORDER_COLUMNS.contains(orderBy)) {
+            throw new IllegalArgumentException("Invalid order by field: " + orderBy);
+        }
+        if (sortDirection == null || !ALLOWED_SORT_DIRECTIONS.contains(sortDirection.toUpperCase())) {
+            throw new IllegalArgumentException("Invalid sort direction: " + sortDirection);
+        }
+        return userMapper.getUsersByOrder(orderBy, sortDirection.toUpperCase());
+    }
+
+    /**
+     * Get all users
+     *
+     * @return User list
+     */
+    public List<User> getAllUsers() {
+        return userMapper.getAllUsers();
+    }
+}

